import re

with open\('D:/documents/volcarch-repo/docs/EXPERIMENT_INDEX.md', 'r', encoding='utf-8'\) as f:
    lines = f.readlines\(\)

status_counts = {}
exp_status = {}
for line in lines:
    if line.startswith\('|'\) and 'E' in line:
        parts = [p.strip\(\) for p in line.split\('|'\)]
        if len\(parts\) > 3 and parts[1].startswith\('E'\):
            exp = parts[1]
            status = parts[3].replace\('**',''\).replace\('~~',''\)
            if status and status not in ['Status', '']:
                exp_status[exp] = status
                status_counts[status] = status_counts.get\(status, 0\) + 1

print\("=== STATUS BREAKDOWN ==="\)
for status in sorted\(status_counts.keys\(\)\):
    print\(f"{status}: {status_counts[status]}"\)

print\("\\n=== FAILED/INCONCLUSIVE EXPERIMENTS ==="\)
for exp, status in sorted\(exp_status.items\(\)\):
    if status in ['FAILED', 'INCONCLUSIVE', 'MIXED', 'PARTIAL', 'CONDITIONAL']:
        print\(f"{exp}: {status}"\)
